 @Test void marineProposalRequiresAnIdfNumber(){assertThatThrownBy(()->ReflectionTestUtils.invokeMethod(service,"validateProposal","MARINE_CARGO","GOODS",Map.of("consignments",List.of(Map.of("transportMode","SEA"))))).isInstanceOf(PMSCustomException.class);}
 @Test void marineProposalAcceptsSeveralConsignments(){assertThatCode(()->ReflectionTestUtils.invokeMethod(service,"validateProposal","MARINE_CARGO","GOODS",Map.of("consignments",List.of(marineRow("IDF-1","SEA","500000"),marineRow("IDF-2","AIR","750000"))))).doesNotThrowAnyException();}
 @Test void marineTotalUsesDeclaredFobValues(){Map<String,Object> normalized=ReflectionTestUtils.invokeMethod(service,"normalizedProposal","MARINE_CARGO",Map.of("consignments",List.of(marineRow("IDF-1","SEA","500000"),marineRow("IDF-2","AIR","750000"))));assertThat(normalized.get("totalFobValue")).isEqualTo(new BigDecimal("1250000"));}
 @Test void marineOcrReferenceRejectsChangedDeclarationValues()throws Exception{Map<String,Object> trusted=marineRow("IDF-1","SEA","500000");Map<String,Object> row=new LinkedHashMap<>(trusted);row.put("extractionReference",Base64.getUrlEncoder().withoutPadding().encodeToString(new byte[]{1,2,3}));when(users.getUserId()).thenReturn(77L);when(encryptionService.decrypt(any(byte[].class))).thenReturn(new DecryptDTO(false,"trusted-claim"));when(objectMapper.readValue(eq("trusted-claim"),ArgumentMatchers.<com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>>any())).thenReturn(Map.of("userId",77,"expiresAt",java.time.Instant.now().plusSeconds(3600).toString(),"fields",trusted));assertThatCode(()->ReflectionTestUtils.invokeMethod(service,"validateMarineOcrReferences",Map.of("consignments",List.of(row)))).doesNotThrowAnyException();row.put("fobValue","1");assertThatThrownBy(()->ReflectionTestUtils.invokeMethod(service,"validateMarineOcrReferences",Map.of("consignments",List.of(row)))).isInstanceOf(PMSCustomException.class);}
 @Test void travelProposalAcceptsMultipleTrips(){assertThatCode(()->ReflectionTestUtils.invokeMethod(service,"validateProposal","TRAVEL","PERSON",Map.of("trips",List.of(Map.of("dateOfBirth","1990-01-01","travelDuration","14 days","destination","Rwanda","purpose","Business"),Map.of("dateOfBirth","1990-01-01","travelDuration","7 days","destination","Tanzania","purpose","Holiday"))))).doesNotThrowAnyException();}
