 @Test void goodsInTransitAcceptsSpecifiedPrimeMoverDetails(){Map<String,Object> proposal=new HashMap<>();proposal.put("cargoItems",List.of(Map.of("singleCarryValue","100000","annualCarryValue","1000000","cargoDescription","Packaged food"),Map.of("singleCarryValue","50000","annualCarryValue","300000","cargoDescription","Furniture")));proposal.put("conveyanceMode","Road");proposal.put("territorialLimits","Kenya");proposal.put("packaging","Sealed cartons");proposal.put("temporaryGarageSafety","Guarded yard");proposal.put("usesHiredVehicles","NO");proposal.put("trackingDevices","YES");proposal.put("engineImmobilizers","YES");proposal.put("specifiedVehicleCover","YES");proposal.put("specifiedVehicles",List.of(Map.of("vehicleType","PRIME_MOVER","make","Mercedes","registrationNumber","KDA 123A","tonnage","20","sumInsured","8000000")));assertThatCode(()->ReflectionTestUtils.invokeMethod(service,"validateProposal","GOODS_IN_TRANSIT","GOODS",proposal)).doesNotThrowAnyException();}
