 @Test void quoteCanBeBoundOnlyToTheVerifiedResponseForThatCaseAndInsurer(){InsuranceAgency agency=new InsuranceAgency();agency.setId(1L);InsuranceCase insuranceCase=new InsuranceCase();insuranceCase.setId(8L);insuranceCase.setAgencyId(1L);insuranceCase.setReference("INS-8");insuranceCase.setStatus("SUBMITTED");org.pms.silverocean.database.pms.entities.InsuranceCompany company=new org.pms.silverocean.database.pms.entities.InsuranceCompany();company.setId(3L);company.setAgencyId(1L);company.setCode("APA");company.setName("APA Insurance");company.setActive(true);org.pms.silverocean.database.pms.entities.InsuranceEmailExchange response=new org.pms.silverocean.database.pms.entities.InsuranceEmailExchange();response.setId(41L);response.setCompanyId(3L);response.setCaseReference("INS-8");response.setMessageType("QUOTATION_REQUEST");response.setDirection("INBOUND");response.setStatus("RECEIVED_VERIFIED");response.setActive(true);when(cases.findByIdForUpdate(8L)).thenReturn(Optional.of(insuranceCase));when(agencies.findByCodeAndActiveTrue("SILVERWOOD")).thenReturn(Optional.of(agency));when(companies.findById(3L)).thenReturn(Optional.of(company));when(emailExchanges.findById(41L)).thenReturn(Optional.of(response));when(users.getUserId()).thenReturn(19L);when(quotes.save(any())).thenAnswer(invocation->{InsuranceQuote saved=invocation.getArgument(0);saved.setId(51L);return saved;});InsuranceModels.QuoteView saved=service.addQuote(8L,new InsuranceModels.QuoteRequest(3L,"APA-001","KES",new BigDecimal("1000"),new BigDecimal("50"),new BigDecimal("1050"),null,"Comprehensive cover",null,LocalDate.now().plusDays(14),41L));assertThat(saved.sourceExchangeId()).isEqualTo(41L);verify(quotes).save(argThat(value->Objects.equals(value.getSourceExchangeId(),41L)));}
 @Test void unverifiedEmailResponseCannotBecomeACustomerQuote(){InsuranceAgency agency=new InsuranceAgency();agency.setId(1L);InsuranceCase insuranceCase=new InsuranceCase();insuranceCase.setId(8L);insuranceCase.setAgencyId(1L);insuranceCase.setReference("INS-8");insuranceCase.setStatus("SUBMITTED");org.pms.silverocean.database.pms.entities.InsuranceCompany company=new org.pms.silverocean.database.pms.entities.InsuranceCompany();company.setId(3L);company.setAgencyId(1L);company.setActive(true);org.pms.silverocean.database.pms.entities.InsuranceEmailExchange response=new org.pms.silverocean.database.pms.entities.InsuranceEmailExchange();response.setId(41L);response.setCompanyId(3L);response.setCaseReference("INS-8");response.setMessageType("QUOTATION_REQUEST");response.setDirection("INBOUND");response.setStatus("RECEIVED_UNVERIFIED");response.setActive(true);when(cases.findByIdForUpdate(8L)).thenReturn(Optional.of(insuranceCase));when(agencies.findByCodeAndActiveTrue("SILVERWOOD")).thenReturn(Optional.of(agency));when(companies.findById(3L)).thenReturn(Optional.of(company));when(emailExchanges.findById(41L)).thenReturn(Optional.of(response));assertThatThrownBy(()->service.addQuote(8L,new InsuranceModels.QuoteRequest(3L,"APA-001","KES",new BigDecimal("1000"),new BigDecimal("50"),new BigDecimal("1050"),null,"Comprehensive cover",null,LocalDate.now().plusDays(14),41L))).isInstanceOf(PMSCustomException.class);verify(quotes,never()).save(any());}
 private Map<String,Object> marineRow(String idf,String mode,String fob){return Map.ofEntries(Map.entry("idfNumber",idf),Map.entry("importerName","Example Importer Limited"),Map.entry("importerPin","P051234567A"),Map.entry("origin","China"),Map.entry("portOfDischarge","Mombasa"),Map.entry("hsCode","8703.23.90"),Map.entry("descriptionAndApplication","Motor vehicle spare parts"),Map.entry("fobValue",fob),Map.entry("transportMode",mode),Map.entry("netMass","1500"),Map.entry("quantity","12"),Map.entry("unitOfMeasure","PCS"));}
 private InsuranceCase pendingAssignment(long adviserId){InsuranceAgency agency=new InsuranceAgency();agency.setId(1L);InsuranceCase insuranceCase=new InsuranceCase();insuranceCase.setId(8L);insuranceCase.setAgencyId(1L);insuranceCase.setStatus("ASSIGNMENT_PENDING");insuranceCase.setAssignedAdviserId(adviserId);insuranceCase.setAssignmentOfferedAt(LocalDateTime.now().minusMinutes(5));when(agencies.findByCodeAndActiveTrue("SILVERWOOD")).thenReturn(Optional.of(agency));when(cases.findByIdForUpdate(8L)).thenReturn(Optional.of(insuranceCase));return insuranceCase;}
 private void stubMarineCaseDocuments(List<InsuranceDocument> caseDocuments){InsuranceAgency agency=new InsuranceAgency();agency.setId(1L);InsuranceCase insuranceCase=new InsuranceCase();insuranceCase.setId(8L);insuranceCase.setAgencyId(1L);insuranceCase.setProductCode("MARINE_CARGO");insuranceCase.setActive(true);when(agencies.findByCodeAndActiveTrue("SILVERWOOD")).thenReturn(Optional.of(agency));when(cases.findById(8L)).thenReturn(Optional.of(insuranceCase));when(documents.findAllByCaseIdAndActiveTrueOrderByCreatedOnDesc(8L)).thenReturn(caseDocuments);}
